<?php defined('_JEXEC') or die;use Joomla\CMS\HTML\HTMLHelper;use Joomla\CMS\Router\Route;?>
<form action="<?php echo Route::_('index.php?option=com_academy&view=polls');?>" method="post" id="adminForm"><p><a class="btn btn-success" href="<?php echo Route::_('index.php?option=com_academy&view=poll');?>">New Poll</a> <button class="btn btn-danger" name="task" value="polls.delete">Delete</button></p><table class="table"><thead><tr><th></th><th>Question</th><th>Status</th><th>Voting period</th><th>Votes</th><th>Report</th></tr></thead><tbody><?php foreach($this->items as $i=>$item):?><tr><td><?php echo HTMLHelper::_('grid.id',$i,$item->id);?></td><td><a href="<?php echo Route::_('index.php?option=com_academy&view=poll&id='.(int)$item->id);?>"><?php echo htmlspecialchars($item->title,ENT_QUOTES,'UTF-8');?></a></td><td><?php echo $item->state?'Published':'Unpublished';?></td><td><?php echo htmlspecialchars(($item->publish_up?:'Immediately').' — '.($item->publish_down?:'No closing date'),ENT_QUOTES,'UTF-8');?></td><td><?php echo (int)$item->votes;?></td><td><a class="btn btn-sm btn-outline-primary" href="<?php echo Route::_('index.php?option=com_academy&task=polls.export&poll_id='.(int)$item->id);?>">Export CSV</a></td></tr><?php endforeach;?></tbody></table><?php echo HTMLHelper::_('form.token');?></form>
